"""parche-107: CONOCIMIENTO GENERAL. 10 cartuchos mundo_* (animales, plantas, cuerpo, comida, objetos, personas, lugares, materiales, naturaleza, tiempo) con ~1.800 palabras corrientes
del espanol y unos 2.400 hechos (~2.300 conceptos) "X es un Y" / "X es parte de Y", sacados del diccionario de conceptos. Se instalan en cartuchos/ SIN insertar (no cambian nada hasta que los insertes):
en la interfaz (pestana Cartuchos, "Insertar todos") o con python -m scripts.construir_mundo --insertar.
 - Arreglo: los hechos de un cartucho ya no hacen que la memoria "gane" al diccionario en preguntas como "para que sirve un martillo" (solo manda lo que ensena la persona).
 - Interfaz: botones "Insertar todos" / "Retirar todos" en Cartuchos.
 - scripts/construir_mundo.py regenera los cartuchos (necesita pip install wordfreq solo para construir).
Uso: python -m scripts.ciclo parche-107.py"""
import datetime, py_compile, shutil, sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
import base64, json, zlib
ALL_EDITS = [('src/language/conceptos.py', '    for f in getattr(mem, "facts", []):\n        sj = nrm(f["s"])\n        if any(sj == w or _st(sj) == _st(w) for w in ws) and (not _es_clase(mem, f["s"]) or f.get("source") != "semilla"):\n            return True\n    return False\n', '    for f in getattr(mem, "facts", []):\n        sj = nrm(f["s"])\n        if any(sj == w or _st(sj) == _st(w) for w in ws) and (not _es_clase(mem, f["s"]) or (f.get("source") != "semilla" and not f.get("cart"))):\n            return True\n    return False\n', '        if any(sj == w or _st(sj) == _st(w) for w in ws) and (not _es_clase(mem, f["s"]) or (f.get("source") != "semilla" and not f.get("cart"))):'), ('src/language/conceptos.py', '        return None                                                              # solo palabras del espanol\n    for f in getattr(mem, "facts", []):\n        if _st(f["s"]) == _st(pal) and (not _es_clase(mem, f["s"]) or f.get("source") != "semilla"):\n            return None                                                          # lo que la persona ha ensenado (o una entidad) manda; el complemento es para el conocimiento de fabrica\n    r = describir(pal, mem)\n', '        return None                                                              # solo palabras del espanol\n    for f in getattr(mem, "facts", []):\n        if _st(f["s"]) == _st(pal) and (not _es_clase(mem, f["s"]) or (f.get("source") != "semilla" and not f.get("cart"))):\n            return None                                                          # lo que la persona ha ensenado (o una entidad) manda; el complemento es para el conocimiento de fabrica\n    r = describir(pal, mem)\n', '        if _st(f["s"]) == _st(pal) and (not _es_clase(mem, f["s"]) or (f.get("source") != "semilla" and not f.get("cart"))):'), ('src/web/static/index.html', '      <div style="display:flex;flex-direction:column;flex:1;min-width:0;min-height:0">\n        <div class="cab"><div><h1>Cartuchos</h1><p>Paquetes de conocimiento que puedes insertar, retirar, compartir o crear.</p></div><div class="sp"></div>\n          <button class="btn" id="ca-mem" type="button">Guardar mi memoria como cartucho</button><button class="btn pri" id="ca-txt" type="button">Crear desde un texto</button></div>\n        <div class="lienzo">\n          <div class="metricas" id="ca-met"></div>\n', '      <div style="display:flex;flex-direction:column;flex:1;min-width:0;min-height:0">\n        <div class="cab"><div><h1>Cartuchos</h1><p>Paquetes de conocimiento que puedes insertar, retirar, compartir o crear.</p></div><div class="sp"></div>\n          <button class="btn" id="ca-todos" type="button">Insertar todos</button><button class="btn" id="ca-ninguno" type="button">Retirar todos</button><button class="btn" id="ca-mem" type="button">Guardar mi memoria como cartucho</button><button class="btn pri" id="ca-txt" type="button">Crear desde un texto</button></div>\n        <div class="lienzo">\n          <div class="metricas" id="ca-met"></div>\n', '          <button class="btn" id="ca-todos" type="button">Insertar todos</button><button class="btn" id="ca-ninguno" type="button">Retirar todos</button><button class="btn" id="ca-mem" type="button">Guardar mi memoria como cartucho</button><button class="btn pri" id="ca-txt" type="button">Crear desde un texto</button></div>'), ('src/web/static/index.html', '  if(r.ok){aviso(`Cartucho «${r.nombre}» cargado (${r.hechos} hechos). Insértalo con el interruptor.`);cargarCartuchos()}\n}\n$("#ca-sel").onclick=()=>$("#ca-file").click(); $("#ca-file").onchange=e=>{procesarArchivo(e.target.files[0]);e.target.value=""};\nconst Z=$("#ca-zona"); ["dragenter","dragover"].forEach(ev=>Z.addEventListener(ev,e=>{e.preventDefault();Z.classList.add("sobre")})); ["dragleave","drop"].forEach(ev=>Z.addEventListener(ev,e=>{e.preventDefault();Z.classList.remove("sobre")}));\n', '  if(r.ok){aviso(`Cartucho «${r.nombre}» cargado (${r.hechos} hechos). Insértalo con el interruptor.`);cargarCartuchos()}\n}\nasync function todos(on){const r=await api("/api/cartuchos");if(r.error)return;let n=0;for(const c of r.cartuchos){if(c.activo!==on){const x=await api("/api/cartucho/activar",{n:c.nombre,activo:on});if(x.ok)n++}}aviso(n?(on?`${n} cartuchos insertados`:`${n} cartuchos retirados`):"Nada que cambiar");cargarCartuchos()}\n$("#ca-todos").onclick=()=>todos(true); $("#ca-ninguno").onclick=()=>todos(false);\n$("#ca-sel").onclick=()=>$("#ca-file").click(); $("#ca-file").onchange=e=>{procesarArchivo(e.target.files[0]);e.target.value=""};\nconst Z=$("#ca-zona"); ["dragenter","dragover"].forEach(ev=>Z.addEventListener(ev,e=>{e.preventDefault();Z.classList.add("sobre")})); ["dragleave","drop"].forEach(ev=>Z.addEventListener(ev,e=>{e.preventDefault();Z.classList.remove("sobre")}));\n', 'async function todos(on){const r=await api("/api/cartuchos");if(r.error)return;let n=0;for(const c of r.cartuchos){if(c.activo!==on){const x=await api("/api/cartucho/activar",{n:c.nombre,activo:on});if(x.ok)n++}}aviso(n?(on?`${n} cartuchos insertados`:`${n} cartuchos retirados`):"Nada que cambiar");cargarCartuchos()}')]
NEW_FILES = {'scripts/construir_mundo.py': '"""parche-107: genera cartuchos de CONOCIMIENTO GENERAL a partir del diccionario de conceptos (WordNet + OMW, data/conceptos.json.gz).\n\n    python -m scripts.construir_mundo            # escribe cartuchos/mundo_*.json (no los inserta)\n    python -m scripts.construir_mundo --insertar # ademas los inserta\n\nPor cada dominio (animales, plantas, cuerpo, comida, objetos, personas, lugares, materiales, naturaleza, tiempo) elige las palabras espanolas corrientes y escribe\nhechos "X es un Y" (siguiendo la cadena de hiperonimos hasta lo abstracto) y "X es parte de Y". Solo para CONSTRUIR usa el listado de frecuencias `wordfreq`\n(pip install wordfreq; datos CC BY-SA); los cartuchos resultantes no lo necesitan. Es determinista: misma entrada, mismos cartuchos."""\nimport argparse\nimport json\nimport os\nimport re\nimport sys\nimport time\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nDOMINIOS = {\n    "animales": ([5], 2.6, 900), "plantas": ([20], 2.6, 500), "cuerpo": ([8], 2.6, 400), "comida": ([13], 2.6, 600), "objetos": ([6], 3.0, 1500),\n    "personas": ([18], 3.0, 1200), "lugares": ([15, 17], 3.0, 500), "materiales": ([27], 2.8, 500), "naturaleza": ([19], 2.8, 200), "tiempo": ([28], 3.0, 250),\n}\nDESCRIPCION = {"animales": "Animales y su clasificación", "plantas": "Plantas, flores y árboles", "cuerpo": "Partes del cuerpo", "comida": "Comidas y bebidas", "objetos": "Objetos, edificios y herramientas",\n               "personas": "Personas, oficios y parentescos", "lugares": "Lugares y accidentes geográficos", "materiales": "Materiales y sustancias", "naturaleza": "Fenómenos de la naturaleza",\n               "tiempo": "Tiempo, días, meses y estaciones"}\nOK = re.compile(r"^[a-záéíóúüñ]{3,}$")\nEXCLUIR = {"sus", "jorge", "argentina", "virus", "euro", "mierda", "bonito", "mezquita", "salado", "atlas", "son", "mayo", "dios", "internet", "especial", "general", "bien", "gen", "recto", "clara", "maría", "alguien", "gente", "cosa", "peludo", "grano", "variable", "paralelo", "diez", "máster", "radical", "olímpico", "sureño"}\nSIN_PLURAL = {"lunes", "martes", "miércoles", "jueves", "viernes", "crisis", "tijeras", "gafas", "vacaciones", "análisis", "pantalones"}\n\n\ndef construir(salida="cartuchos", insertar=False, log=print):\n    from wordfreq import top_n_list, zipf_frequency\n    from src.language import conceptos as C\n    from src.memory import cartuchos\n    d = C._load()\n    parada = set(top_n_list("es", 250))\n    memo = {}\n\n    def mejor(c):\n        ws = [w for w in C.nombres(c) if OK.match(w)]\n        sc = [(zipf_frequency(w, "es"), w) for w in ws if not (w.endswith("s") and (w[:-1] in ws or w[:-2] in ws))]\n        return max(sc) if sc else (0.0, None)\n\n    def lab(c):\n        if c not in memo:\n            e = C.etiqueta(c)\n            if e in C.ETIQUETA_ES.values():\n                memo[c] = e\n            else:\n                z, w = mejor(c)\n                memo[c] = w or (e if e and OK.match(e) else None)\n        return memo[c]\n\n    def plural(w):\n        if not w or not w.endswith("s") or w in SIN_PLURAL or len(w) < 4:\n            return False\n        sing = [w[:-1]] + ([w[:-2]] if w.endswith("es") else []) + ([w[:-3] + "z"] if w.endswith("ces") else [])\n        return any(zipf_frequency(x, "es") >= 2.5 for x in sing)\n\n    def abstracto(l):\n        return (not l) or l.lower() in C.ALTO or l.lower() in C.TAXON or l in C.OMITIR or l in EXCLUIR or plural(l) or (l not in C.ETIQUETA_ES.values() and zipf_frequency(l, "es") < 1.2)\n\n    def zipf(c):\n        l = lab(c)\n        return zipf_frequency(l, "es") if l else 0.0\n\n    res = []\n    usados = {}\n    for nombre, (lx, umbral, tope) in DOMINIOS.items():\n        cand = []\n        for c in range(d["n"]):\n            if d["pos"][c] != "n" or d["lex"][c] not in lx:\n                continue\n            l = lab(c)\n            if not l or l in EXCLUIR or l in parada or plural(l) or usados.get(l, nombre) != nombre:\n                continue\n            z = zipf_frequency(l, "es")\n            if z < umbral or C.conceptos(l)[:1] != [c] or C.es_genero(c):\n                continue\n            cand.append((-z, l, c))\n        cand.sort()\n        cand = cand[:tope]\n        hechos, vistos, disp = [], set(), {}\n\n        def hecho(s, p, o):\n            k = (s.upper(), p, o.upper())\n            if k not in vistos and s.upper() != o.upper():\n                vistos.add(k)\n                hechos.append({"s": k[0], "p": p, "o": k[2], "n": 1, "source": "mundo", "imp": 1.0, "tick": 0, "archived": False, "neg": False, "when": "", "when_disp": "", "when_abs": None, "q": ""})\n                disp.setdefault(k[0], s)\n                disp.setdefault(k[2], o)\n\n        for _, l, c in cand:\n            usados[l] = nombre\n            x, cur, prof, ult = c, l, 0, set()\n            while prof < 9:\n                ts = [t for t in d["hyp"].get(x, []) if t not in ult]\n                if not ts:\n                    break\n                x = ts[0]\n                ult.add(x)\n                lx_ = lab(x)\n                if abstracto(lx_) or lx_ == cur:\n                    if lx_ and lx_.lower() in C.ALTO:\n                        break\n                    continue\n                hecho(cur, "ES", lx_)\n                cur, prof = lx_, prof + 1\n            for t in d["parte"].get(c, []):\n                lt = lab(t)\n                if lt and not abstracto(lt) and zipf_frequency(lt, "es") >= 3.0 and lt != l:\n                    hecho(lt, "PARTE_DE", l)\n        nom = "mundo_" + nombre\n        cont = {"hechos": hechos, "alias": {}, "verb_isa": {}, "defs": {}, "surface": {}, "display": disp, "opposites": []}\n        cartuchos.guardar_cartucho(nom, cont, {"fuente": "diccionario de conceptos (WordNet 3.0 + OMW)", "descripcion": DESCRIPCION[nombre], "frases": len(cand), "creado": time.strftime("%Y-%m-%d %H:%M")}, salida)\n        ents = {h["s"] for h in hechos} | {h["o"] for h in hechos}\n        log(f"{nom}: {len(cand)} palabras, {len(hechos)} hechos, {len(ents)} conceptos")\n        res.append((nom, len(hechos), len(ents)))\n        if insertar:\n            cartuchos.insertar(nom, salida)\n    return res\n\n\nif __name__ == "__main__":\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--salida", default="cartuchos")\n    ap.add_argument("--insertar", action="store_true")\n    a = ap.parse_args()\n    construir(a.salida, a.insertar)\n', 'tests/test_parche107.py': '"""parche-107: cartuchos de conocimiento general (mundo_*) y su convivencia con el diccionario."""\nimport json\nimport os\nimport tempfile\n\nimport pytest\n\nfrom src.language import conceptos as C\nfrom src.memory import cartuchos\nfrom src.memory.store import MemoryStore\n\n\nclass _M:\n    def __init__(self, facts, display=None):\n        self.facts, self.display = facts, display or {}\n\n\ndef _f(s, p, o, **k):\n    return {"s": s, "p": p, "o": o, "neg": False, **k}\n\n\ndef test_los_hechos_de_cartucho_no_silencian_el_diccionario():\n    m = _M([_f("MARTILLO", "ES", "HERRAMIENTA", cart="mundo_objetos", source="mundo")], {"MARTILLO": "martillo", "HERRAMIENTA": "herramienta"})\n    assert not C._conoce(m, "para que sirve un martillo")\n    assert C.antes("¿Para qué sirve un martillo?", m) is not None\n    assert C.complemento("¿Qué es un martillo?", m) is not None\n\n\ndef test_lo_que_ensena_la_persona_sigue_mandando():\n    m = _M([_f("MARTILLO", "ES", "HERRAMIENTA", source="usuario")], {"MARTILLO": "martillo", "HERRAMIENTA": "herramienta"})\n    assert C._conoce(m, "para que sirve un martillo")\n\n\ndef test_cartuchos_mundo_montan_y_se_retiran():\n    d = tempfile.mkdtemp()\n    h = [{"s": "PERRO", "p": "ES", "o": "ANIMAL", "n": 1, "t": 0, "source": "mundo", "imp": 1.0, "tick": 0, "archived": False, "neg": False, "when": "", "when_disp": "", "when_abs": None, "q": ""}]\n    cartuchos.guardar_cartucho("mundo_x", {"hechos": h, "display": {"PERRO": "perro"}}, base=d)\n    cartuchos.insertar("mundo_x", d)\n    mem = MemoryStore(os.path.join(d, "m.json"))\n    assert cartuchos.montar(mem, d) == [("mundo_x", 1)]\n    assert mem.display["PERRO"] == "perro"\n    cartuchos.retirar("mundo_x", d)\n    cartuchos.montar(mem, d)\n    assert not mem.facts\n\n\ndef test_cartuchos_generados_si_estan_instalados():\n    base = "cartuchos"\n    nombres = [n for n, *_ in cartuchos.listar(base) if n.startswith("mundo_")]\n    if not nombres:\n        pytest.skip("cartuchos mundo_* no instalados")\n    total = 0\n    for n in nombres:\n        c = cartuchos.cargar(n, base)\n        assert c["hechos"] and all(h["p"] in ("ES", "PARTE_DE") and h["s"] != h["o"] for h in c["hechos"])\n        total += len(c["hechos"])\n    assert total > 2000\n'}
SOFT = []
BLOB = ''

def main(root: Path = ROOT) -> int:
    stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S-%f")
    bk = root / ".parche_backups" / stamp
    texts, changed = {}, set()
    for rel, old, new, marca in ALL_EDITS:                              # comprobar TODO antes de escribir nada
        p = root / rel
        if not p.is_file():
            print(f"FALTA {rel}: no se toca nada."); return 1
        txt = texts[rel] if rel in texts else p.read_text(encoding="utf-8")
        if marca in txt:
            texts[rel] = txt; continue
        if txt.count(old) != 1:
            print(f"ERROR {rel}: un trozo a cambiar aparece {txt.count(old)} veces (debe ser 1): {old[:70]!r}. No se toca nada."); return 1
        texts[rel] = txt.replace(old, new); changed.add(rel)
    plan = [(root / rel, rel, texts[rel]) for rel in sorted(changed)]
    CART = json.loads(zlib.decompress(base64.b64decode(BLOB)).decode("utf-8"))
    for nom, cont in CART.items():
        pc = root / "cartuchos" / nom
        txt = json.dumps(cont, ensure_ascii=False, separators=(",", ":"))
        if not pc.exists() or pc.read_text(encoding="utf-8") != txt:
            pc.parent.mkdir(parents=True, exist_ok=True)
            if pc.exists():
                (bk / "cartuchos").mkdir(parents=True, exist_ok=True); shutil.copy2(pc, bk / "cartuchos" / nom)
            pc.write_text(txt, encoding="utf-8"); print(f"  escrito cartuchos/{nom} (sin insertar)")
    for rel, content in NEW_FILES.items():
        p = root / rel
        if not p.exists() or p.read_text(encoding="utf-8") != content:
            plan.append((p, rel, content))
    for p, rel, txt in plan:
        if p.exists():
            (bk / rel).parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(p, bk / rel)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(txt, encoding="utf-8")
        if rel.endswith(".py"):
            py_compile.compile(str(p), doraise=True)
        print(f"  escrito {rel}")

    for rel, marca, bloque, antes in SOFT:                              # documentacion: tolerante, nunca bloquea
        p = root / rel
        try:
            t = p.read_text(encoding="utf-8") if p.exists() else ""
            if marca in t:
                continue
            if antes and antes in t:
                t = t.replace(antes, bloque + antes, 1)
            else:
                t = t + ("" if t.endswith("\n") or not t else "\n") + bloque
            if p.exists():
                (bk / rel).parent.mkdir(parents=True, exist_ok=True); shutil.copy2(p, bk / rel)
            p.write_text(t, encoding="utf-8"); print(f"  actualizado {rel}")
        except Exception as e:
            print(f"  (aviso) no se pudo actualizar {rel}: {e!r}")
    print(f"parche-107 instalado. Copias en {bk}" if plan else "parche-107: nada que hacer.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

